import com.fream.back.domain.m10.service.command.Xzz58CommandService;
import com.fream.back.domain.m13.entity.Xbr34;
import com.fream.back.domain.m13.entity.Xrd81;
import com.fream.back.global.config.Xsd33Config;
import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.context.ApplicationContext;
import org.springframework.context.annotation.Import;
import org.springframework.test.context.ActiveProfiles;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;




@DataJpaTest
@AutoConfigureTestDatabase(replace = AutoConfigureTestDatabase.Replace.NONE)
@ActiveProfiles("test")
@Import(Xsd33Config.class)
class ListingAlertTest {

    @Autowired EntityManager em;
    @Autowired ApplicationContext ctx;

    private static int seq = 0;

    private Xrd81 user(String prefix) {
        seq++;
        Xrd81 u = Xrd81.builder().email(prefix + "-v6-" + seq + "@test.com").password("pw").referralCode("v6-" + seq)
                .phoneNumber("010-6000-" + seq).build();
        em.persist(u);
        return u;
    }

    private List<Xkh73> favoriteAlertsOf(Xrd81 u) {
        return em.createQuery("select n from Xkh73 n where n.user.id = :uid", Xkh73.class)
                .setParameter("uid", u.getId()).getResultList().stream()
                .filter(n -> n.getType() == Xkh73Type.FAVORITE).toList();
    }

    @Test
    void newListingAlertsUsersInterestedInThatColorOnly() {
        Xrd81 seller = user("seller");
        em.persist(Xbr34.builder().user(seller).bankName("국민").accountNumber("111-222").accountHolder("판매자").build());
        Xrd81 whiteFan = user("white-fan");
        Xrd81 blackFan = user("black-fan");

        Xkr46 product = Xkr46.builder().name("에어 포스 1").englishName("Air Force 1").releasePrice(139000)
                .modelNumber("AF-1").releaseDate("2024-01-01").gender(Xbj22Type.UNISEX).build();
        em.persist(product);
        Xfp92 white = Xfp92.builder().colorName("White").product(product).build();
        Xfp92 black = Xfp92.builder().colorName("Black").product(product).build();
        em.persist(white);
        em.persist(black);
        Xdh20 white260 = Xdh20.builder().sizeType(Xnp24Type.SHOES).size("260")
                .purchasePrice(139000).salePrice(139000).quantity(1).productColor(white).build();
        em.persist(white260);
        em.persist(Xrf21.builder().user(whiteFan).productColor(white).build());
        em.persist(Xrf21.builder().user(blackFan).productColor(black).build());
        em.flush();
        em.clear();

        new Wiring(ctx).get(Xzz58CommandService.class)
                .createSaleBid(seller.getEmail(), white260.getId(), 150000, "서울", "12345", "010-0000-0000", false);
        em.flush();
        em.clear();

        List<Xkh73> alerts = favoriteAlertsOf(whiteFan);
        assertThat(alerts).hasSize(1);
        assertThat(alerts.get(0).getMessage()).contains("에어 포스 1");
        assertThat(favoriteAlertsOf(blackFan)).isEmpty();
    }
}
package com.fream.back.visible.t06;

import org.mockito.Mockito;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.ApplicationContext;
import org.springframework.context.ApplicationEvent;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.context.PayloadApplicationEvent;
import org.springframework.context.annotation.ClassPathScanningCandidateComponentProvider;
import org.springframework.context.event.EventListener;
import org.springframework.core.type.filter.AnnotationTypeFilter;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionalEventListener;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;









final class Wiring {

    private static final String DOMAIN = "com.fream.back.domain";

    private final ApplicationContext ctx;
    private final Map<Class<?>, Object> instances = new HashMap<>();
    private final Set<Class<?>> building = new HashSet<>();
    private List<Class<?>> listenerClasses;

    Wiring(ApplicationContext ctx) {
        this.ctx = ctx;
        instances.put(ApplicationEventPublisher.class, (ApplicationEventPublisher) this::dispatch);
    }

    <T> Wiring with(Class<T> type, T instance) {
        instances.put(type, instance);
        return this;
    }

    @SuppressWarnings("unchecked")
    <T> T get(Class<T> type) {
        Object existing = instances.get(type);
        if (existing != null) {
            return (T) existing;
        }
        if (type == String.class) {
            return (T) "";
        }
        if (type.isPrimitive()) {
            return (T) defaultPrimitive(type);
        }
        Object bean = ctx.getBeanProvider(type).getIfUnique();
        if (bean != null) {
            return (T) bean;
        }
        Object created;
        if (isDomainComponent(type) && !building.contains(type)) {
            building.add(type);
            try {
                created = construct(type);
            } finally {
                building.remove(type);
            }
        } else {
            created = Mockito.mock(type);
        }
        instances.put(type, created);
        return (T) created;
    }

    private static boolean isDomainComponent(Class<?> t) {
        return t.getName().startsWith(DOMAIN + ".")
                && !t.isInterface()
                && !Modifier.isAbstract(t.getModifiers())
                && org.springframework.core.annotation.AnnotatedElementUtils.hasAnnotation(t, Component.class);
    }

    private Object construct(Class<?> type) {
        try {
            Constructor<?> ctor = null;
            for (Constructor<?> c : type.getDeclaredConstructors()) {
                if (c.isAnnotationPresent(Autowired.class)) {
                    ctor = c;
                }
            }
            if (ctor == null) {
                ctor = java.util.Arrays.stream(type.getDeclaredConstructors())
                        .max(Comparator.comparingInt(Constructor::getParameterCount))
                        .orElseThrow();
            }
            Class<?>[] params = ctor.getParameterTypes();
            Object[] args = new Object[params.length];
            for (int i = 0; i < params.length; i++) {
                args[i] = get(params[i]);
            }
            ctor.setAccessible(true);
            Object obj = ctor.newInstance(args);
            instances.put(type, obj);
            for (Class<?> c = type; c != null && c != Object.class; c = c.getSuperclass()) {
                for (Field f : c.getDeclaredFields()) {
                    if (f.isAnnotationPresent(Autowired.class) && !Modifier.isStatic(f.getModifiers())) {
                        f.setAccessible(true);
                        if (f.get(obj) == null) {
                            f.set(obj, get(f.getType()));
                        }
                    }
                }
            }
            return obj;
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("cannot build " + type.getName(), e);
        }
    }

    private void dispatch(Object event) {
        Object payload = (event instanceof PayloadApplicationEvent<?> p) ? p.getPayload() : event;
        for (Class<?> listenerType : listenerClasses()) {
            for (Method m : listenerType.getDeclaredMethods()) {
                boolean listener = m.isAnnotationPresent(EventListener.class)
                        || m.isAnnotationPresent(TransactionalEventListener.class);
                if (!listener || m.getParameterCount() != 1) {
                    continue;
                }
                Class<?> p = m.getParameterTypes()[0];
                Object arg = p.isInstance(payload) ? payload
                        : (event instanceof ApplicationEvent && p.isInstance(event)) ? event : null;
                if (arg == null) {
                    continue;
                }
                try {
                    m.setAccessible(true);
                    m.invoke(get(listenerType), arg);
                } catch (InvocationTargetException e) {
                    Throwable t = e.getTargetException();
                    if (t instanceof RuntimeException re) {
                        throw re;
                    }
                    throw new IllegalStateException(t);
                } catch (IllegalAccessException e) {
                    throw new IllegalStateException(e);
                }
            }
        }
    }

    private List<Class<?>> listenerClasses() {
        if (listenerClasses == null) {
            listenerClasses = new ArrayList<>();
            ClassPathScanningCandidateComponentProvider scanner = new ClassPathScanningCandidateComponentProvider(false);
            scanner.addIncludeFilter(new AnnotationTypeFilter(Component.class));
            scanner.findCandidateComponents(DOMAIN).forEach(bd -> {
                try {
                    Class<?> c = Class.forName(bd.getBeanClassName());
                    for (Method m : c.getDeclaredMethods()) {
                        if (m.isAnnotationPresent(EventListener.class)
                                || m.isAnnotationPresent(TransactionalEventListener.class)) {
                            listenerClasses.add(c);
                            break;
                        }
                    }
                } catch (ClassNotFoundException | LinkageError ignored) {

                }
            });
        }
        return listenerClasses;
    }

    private static Object defaultPrimitive(Class<?> t) {
        if (t == boolean.class) return false;
        if (t == char.class) return '\0';
        if (t == byte.class) return (byte) 0;
        if (t == short.class) return (short) 0;
        if (t == int.class) return 0;
        if (t == long.class) return 0L;
        if (t == float.class) return 0f;
        return 0d;
    }
}
package com.fream.back.domain.m10.service.command;

import com.fream.back.domain.m16.entity.Xzj27;
import com.fream.back.domain.m16.service.query.Xzj27QueryService;
import com.fream.back.domain.m02.entity.Xdh20;
import com.fream.back.domain.m02.service.p14.Xdh20QueryService;
import com.fream.back.domain.m10.entity.Xtz73Status;
import com.fream.back.domain.m10.entity.Xgg74;
import com.fream.back.domain.m10.entity.Xzz58;
import com.fream.back.domain.m10.repository.Xzz58Repository;
import com.fream.back.domain.m13.entity.Xrd81;
import com.fream.back.domain.m13.service.query.Xrd81QueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class Xzz58CommandService {

    private final Xzz58Repository saleBidRepository;
    private final Xrd81QueryService userQueryService;
    private final Xdh20QueryService productSizeQueryService;
    private final Xgg74CommandService saleCommandService;
    private final Xzj27QueryService orderBidQueryService;
    @Transactional
    public Xzz58 createSaleBid(String sellerEmail, Long productSizeId, int bidPrice,
                                 String returnAddress, String postalCode, String receiverPhone
                                , boolean isWarehouseStorage) {

        Xrd81 seller = userQueryService.findByEmail(sellerEmail);


        Xdh20 productSize = productSizeQueryService.findById(productSizeId)
                .orElseThrow(() -> new IllegalArgumentException("해당 상품 사이즈를 찾을 수 없습니다: " + productSizeId));


        Xgg74 sale = saleCommandService.createSale(seller, productSize, returnAddress, postalCode, receiverPhone,isWarehouseStorage);


        Xzz58 saleBid = Xzz58.builder()
                .seller(seller)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(Xtz73Status.PENDING)
                .sale(sale)
                .build();


        saleBid = saleBidRepository.save(saleBid);


        sale.assignSaleBid(saleBid);


        return saleBid;
    }
    @Transactional
    public Long createInstantSaleBid(Long orderBidId,
                                        String sellerEmail,
                                        String returnAddress,
                                        String postalCode,
                                        String receiverPhone) {

        Xgg74 sale=saleCommandService.createInstantSale(orderBidId,sellerEmail,returnAddress,postalCode,receiverPhone);

        Xzj27 orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));



        Xzz58 saleBid = Xzz58.builder()
                .seller(sale.getSeller())
                .productSize(sale.getProductSize())
                .bidPrice(orderBid.getBidPrice())
                .status(Xtz73Status.MATCHED)
                .sale(sale)
                .order(orderBid.getOrder())
                .build();


        saleBid.assignSale(sale);
        saleBid.assignOrder(orderBid.getOrder());
        sale.assignSaleBid(saleBid);


        saleBidRepository.save(saleBid);


        return sale.getId();
    }

    @Transactional
    public void deleteSaleBid(Long saleBidId) {

        Xzz58 saleBid = saleBidRepository.findById(saleBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 SaleBid를 찾을 수 없습니다: " + saleBidId));


        if (saleBid.getOrder() != null) {
            throw new IllegalStateException("SaleBid는 Order와 연결되어 있으므로 삭제할 수 없습니다.");
        }


        if (saleBid.getSale() != null) {
            saleCommandService.deleteSale(saleBid.getSale().getId());
        }


        saleBidRepository.delete(saleBid);
    }
}
package com.fream.back.domain.m02.repository;

import com.fream.back.domain.m02.dto.Xkr46SearchResponseDto;
import com.fream.back.domain.m02.entity.*;
import com.querydsl.core.Tuple;
import com.querydsl.core.types.OrderSpecifier;
import com.querydsl.jpa.JPAExpressions;
import com.querydsl.jpa.impl.JPAQueryFactory;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageImpl;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;





@Repository
@RequiredArgsConstructor
@Slf4j
public class Xzd96Repository {

    private final JPAQueryFactory queryFactory;









    public Page<Xkr46SearchResponseDto> findUserInterestProducts(
            Long userId,
            Xpk87 sortOption,
            Pageable pageable) {
        log.debug("사용자 관심 상품 목록 조회 시작 - 사용자ID: {}, 페이지: {}, 사이즈: {}",
                userId, pageable.getPageNumber(), pageable.getPageSize());


        QXrf21 interest = QXrf21.xrf21;
        QXrf21 interest1 = new QXrf21("interest1");
        QXkr46 product = QXkr46.xkr46;
        QXfp92 productColor = QXfp92.xfp92;
        QXdh20 productSize = QXdh20.xdh20;
        QXzq99 productImage = QXzq99.xzq99;

        try {

            log.debug("관심 상품 데이터 조회 쿼리 실행 - 사용자ID: {}", userId);
            List<Tuple> results = queryFactory.select(
                            interest.id,
                            product.id,
                            product.name,
                            product.englishName,
                            product.releasePrice,
                            productColor.id,
                            productColor.thumbnailImage.imageUrl,
                            productColor.colorName,
                            productSize.purchasePrice.min(),
                            JPAExpressions
                                    .select(interest1.count())
                                    .from(interest1)
                                    .where(interest1.productColor.eq(productColor))
                    )
                    .from(interest)
                    .leftJoin(interest.productColor, productColor)
                    .leftJoin(productColor.product, product)
                    .leftJoin(productColor.thumbnailImage, productImage)
                    .leftJoin(productColor.sizes, productSize)
                    .leftJoin(productColor.interests, interest1)
                    .where(interest.user.id.eq(userId))
                    .groupBy(
                            product.id,
                            productColor.id,
                            productColor.thumbnailImage.imageUrl)
                    .orderBy(getOrderByClause(sortOption, product, productColor, productSize))
                    .offset(pageable.getOffset())
                    .limit(pageable.getPageSize())
                    .fetch();

            log.debug("관심 상품 데이터 조회 완료 - 결과 수: {}", results.size());


            log.debug("관심 상품 전체 개수 조회 시작 - 사용자ID: {}", userId);
            long total = queryFactory.select(interest.count())
                    .from(interest)
                    .where(interest.user.id.eq(userId))
                    .fetchOne();

            log.debug("관심 상품 전체 개수 조회 완료 - 총 개수: {}", total);


            log.debug("관심 상품 데이터 DTO 변환 시작");
            List<Xkr46SearchResponseDto> content = results.stream()
                    .map(tuple -> {
                        Long interestCount = tuple.get(JPAExpressions
                                .select(interest1.count())
                                .from(interest1)
                                .where(interest1.productColor.eq(productColor)));

                        return Xkr46SearchResponseDto.builder()
                                .id(tuple.get(product.id))
                                .name(tuple.get(product.name))
                                .englishName(tuple.get(product.englishName))
                                .releasePrice(tuple.get(product.releasePrice))
                                .thumbnailImageUrl(tuple.get(productColor.thumbnailImage.imageUrl))
                                .price(tuple.get(productSize.purchasePrice.min()))
                                .colorName(tuple.get(productColor.colorName))
                                .colorId(tuple.get(productColor.id))
                                .interestCount(interestCount)
                                .build();
                    })
                    .collect(Collectors.toList());

            log.debug("관심 상품 데이터 DTO 변환 완료 - DTO 수: {}", content.size());

            Page<Xkr46SearchResponseDto> resultPage = new PageImpl<>(content, pageable, total);
            log.debug("사용자 관심 상품 목록 조회 완료 - 총 결과 수: {}, 총 페이지 수: {}",
                    resultPage.getTotalElements(), resultPage.getTotalPages());

            return resultPage;
        } catch (Exception e) {
            log.error("사용자 관심 상품 목록 조회 중 예상치 못한 오류 발생 - 사용자ID: {}", userId, e);
            throw e;
        }
    }










    private OrderSpecifier<?> getOrderByClause(
            Xpk87 sortOption,
            QXkr46 product,
            QXfp92 productColor,
            QXdh20 productSize) {
        log.debug("정렬 조건 설정 - 정렬 옵션: {}", sortOption);

        String field = sortOption != null ? sortOption.getField() : null;
        String order = sortOption != null ? sortOption.getOrder() : null;

        if (field == null || order == null) {
            log.debug("기본 정렬 적용 - 상품ID 오름차순");
            return product.id.asc();
        }

        if (sortOption != null) {
            log.debug("정렬 옵션 적용 - 필드: {}, 순서: {}", field, order);
            switch (sortOption.getField()) {
                case "price":
                    return "asc".equalsIgnoreCase(sortOption.getOrder())
                            ? productSize.purchasePrice.asc()
                            : productSize.purchasePrice.desc();
                case "releaseDate":
                    return "asc".equalsIgnoreCase(sortOption.getOrder())
                            ? product.releaseDate.asc()
                            : product.releaseDate.desc();
                case "interestCount":
                    return "asc".equalsIgnoreCase(sortOption.getOrder())
                            ? productColor.interests.size().sum().asc()
                            : productColor.interests.size().sum().desc();
                default:
                    log.debug("알 수 없는 정렬 필드 - 기본 정렬 적용: {}", field);
                    break;
            }
        }
        return product.id.asc();
    }
