            List<Xkh73> notifications = createNotificationsForUsers(
                    allUsers, requestDTO.getCategory(), requestDTO.getType(), requestDTO.getMessage());

            List<Xkh73> savedNotifications = notificationRepository.saveAll(notifications);
            log.info("전체 사용자 알림 생성 완료: 카테고리={}, 타입={}, 생성된 알림 수={}",
