        }
    }






    private Xkh73 buildNotification(Xrd81 user, Xzv64 category, Xkh73Type type, String message) {
        return Xkh73.builder()
                .category(category)
                .type(type)
                .message(message)
                .isRead(false)
                .user(user)
                .build();
    }




    private List<Xkh73> createNotificationsForUsers(
            List<Xrd81> users, Xzv64 category, Xkh73Type type, String message) {
        List<Xkh73> notifications = new ArrayList<>();

        for (Xrd81 user : users) {
            Xkh73 notification = buildNotification(user, category, type, message);
            notifications.add(notification);
        }

        return notifications;
    }




    private void broadcastNotificationsToConnectedUsers(List<Xrd81> users, List<Xkh73> notifications) {
        int deliveredCount = 0;

        for (Xrd81 user : users) {
            String redisKey = REDIS_KEY_PREFIX + user.getEmail();

            if (Boolean.TRUE.equals(redisTemplate.hasKey(redisKey))) {
                try {

                    List<Xkh73DTO> userNotifications = notifications.stream()
                            .filter(notification -> notification.getUser().getId().equals(user.getId()))
                            .map(this::toDTO)
                            .collect(Collectors.toList());


                    messagingTemplate.convertAndSendToUser(
                            user.getEmail(),
                            WEBSOCKET_DESTINATION,
                            userNotifications
                    );
                    deliveredCount++;
                } catch (Exception e) {
                    log.warn("사용자 알림 실시간 전송 실패: 사용자={}, 오류={}", user.getEmail(), e.getMessage());

                }
            }
        }

        log.info("실시간 알림 전송 완료: 총 {}명 중 {}명에게 전송됨", users.size(), deliveredCount);
    }




    private void sendRealTimeNotification(String email, Xkh73DTO notification) {
        String redisKey = REDIS_KEY_PREFIX + email;


        if (Boolean.TRUE.equals(redisTemplate.hasKey(redisKey))) {
            try {
                messagingTemplate.convertAndSendToUser(
                        email,
                        WEBSOCKET_DESTINATION,
                        notification
                );
                log.debug("알림 실시간 전송 완료: 사용자={}, 알림ID={}", email, notification.getId());
            } catch (Exception e) {
                log.warn("알림 실시간 전송 실패: 사용자={}, 알림ID={}, 오류={}",
                        email, notification.getId(), e.getMessage());

            }
        } else {
            log.debug("사용자 WebSocket 연결 없음: 사용자={}, 알림은 저장됨", email);
        }
    }




    public void updateWebSocketConnectionTTL(String email) {
        try {
            if (email != null) {
                String redisKey = REDIS_KEY_PREFIX + email;


                Long remainingTime = redisTemplate.getExpire(redisKey, TimeUnit.SECONDS);


                if (remainingTime != null && remainingTime <= 600) {
                    redisTemplate.expire(redisKey, REDIS_TTL_MINUTES, TimeUnit.MINUTES);
                    log.debug("Redis TTL 갱신: 사용자={}, 남은TTL={}초", email, remainingTime);
                } else {
                    log.debug("TTL 연장 불필요: 사용자={}, 남은TTL={}초", email, remainingTime);
                }
            }
        } catch (Exception e) {
            log.error("WebSocket 연결 TTL 갱신 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
            throw new Xkh73Exception(
                    Xkh73ErrorCode.WEBSOCKET_CONNECTION_MAINTENANCE_FAILED,
                    "WebSocket 연결 유지 중 오류가 발생했습니다.",
                    e
            );
        }
    }




    private Xkh73DTO toDTO(Xkh73 notification) {
        return Xkh73DTO.builder()
                .id(notification.getId())
                .category(notification.getCategory())
                .type(notification.getType())
                .message(notification.getMessage())
                .isRead(notification.isRead())
                .createdAt(notification.getCreatedDate().toString())
                .build();
    }




    private List<Xkh73DTO> toDTOList(List<Xkh73> notifications) {
        return notifications.stream()
                .map(this::toDTO)
                .collect(Collectors.toList());
    }
